<script setup lang="ts">
import { computed } from 'vue';import { useRoute } from 'vue-router'
import CanonCanvas from '@/components/canvas/CanonCanvas.vue';import WritingBlockCanvas from '@/components/canvas/WritingBlockCanvas.vue';import ComposerPanel from '@/components/chat/ComposerPanel.vue';import WritingBlock from '@/components/chat/WritingBlock.vue';import ErrorState from '@/components/base/ErrorState.vue';import LoadingState from '@/components/base/LoadingState.vue';import { useCanonAssetsQuery } from '@/queries/canon';import { useWorkspaceStore } from '@/stores/workspace'
const route=useRoute(),workspace=useWorkspaceStore(),projectId=computed(()=>String(route.params.projectId??''));const assetsQuery=useCanonAssetsQuery(projectId);const canvasAsset=computed(()=>assetsQuery.data.value?.find(item=>item.id===workspace.canvasAssetId));
function addBlock(){const block=workspace.createWritingBlock();workspace.openBlock(block.id)}
</script>
<template><main class="workspace-page" :class="{'canvas-active':workspace.canvasOpen}"><section class="chat-column" aria-label="项目对话工作区"><header class="chat-header"><div><p class="eyebrow">Workspace</p><h1 tabindex="-1">创作工作台</h1></div><span class="capability-badge">Chat API 未提供</span></header><div class="message-stream"><div v-if="!workspace.writingBlocks.length" class="chat-empty"><div class="empty-mark">文</div><h2>今天想推进什么？</h2><p>可以打开真实资产 Canvas 或创建一个仅内存的 Writing Block。消息发送将在后端提供 Conversation API 后启用。</p><div class="quick-actions"><RouterLink :to="`/projects/${projectId}/characters`">创建人物</RouterLink><RouterLink :to="`/projects/${projectId}/worldbook`">打开世界书</RouterLink><RouterLink :to="`/projects/${projectId}/outlines`">编辑大纲</RouterLink><button @click="addBlock">新建本地 Writing Block</button></div></div><WritingBlock v-for="block in workspace.writingBlocks" :key="block.id" :title="block.title" :model-value="block.content" @update:model-value="workspace.updateWritingBlock(block.id,$event)" @open-canvas="workspace.openBlock(block.id)"/></div><div class="asset-shelf"><div class="asset-shelf-header"><strong>最近资产</strong><span>从真实正典 API 读取</span></div><LoadingState v-if="assetsQuery.isPending.value" label="加载资产…"/><ErrorState v-else-if="assetsQuery.isError.value" :error="assetsQuery.error.value" @retry="assetsQuery.refetch()"/><div v-else class="asset-shelf-list"><button v-for="asset in assetsQuery.data.value" :key="asset.id" @click="workspace.openAsset(asset.id)"><span>{{ asset.assetType }}</span><strong>{{ asset.name }}</strong></button><p v-if="!assetsQuery.data.value?.length">暂无正典资产，可在项目概览中创建。</p></div></div><ComposerPanel/></section><CanonCanvas v-if="workspace.canvasOpen&&canvasAsset" :project-id="projectId" :asset="canvasAsset"/><WritingBlockCanvas v-else-if="workspace.canvasOpen&&workspace.canvasBlockId"/></main></template>
